INSERT INTO public.source_summary (id, summary) VALUES (1, 'Donald Trump w wywiadzie udzielonym „Wall Street Journal” oświadczył, że codziennie przyjmuje 325 mg aspiryny ze względu na genetyczne predyspozycje do gęstej krwi i dąży do utrzymania „ładnej, rzadkiej” krwi. Wskazał, że lekarze zalecają obniżenie dawki, lecz on nie planuje zmian. Trump przyznał się również do występowania siniaków na dłoniach, które ma ukrywać makijażem, i wyjaśnił, że są wynikiem wrażliwości skóry i częstego brania aspiryny.');
INSERT INTO public.source_summary (id, summary) VALUES (2, 'Anna Kournikova i Enrique Iglesias ogłosili narodziny czwartego dziecka. Para, znana z utrzymywania prywatności, potwierdziła nowy członek rodziny na Instagramie. Wcześniej mają dzieci Lucy, Nicholas (bliźniaki) oraz Mary. Pomimo wcześniejszych spekulacji o kolejnej ciąży, oboje nie komentowali sytuacji przed ogłoszeniem.');
INSERT INTO public.source_summary (id, summary) VALUES (5, 'Viki Gabor potwierdziła na swoim Instagramie, że oficjalnie ma narzeczonego i jest szczęśliwa. Artystka zareagowała na rozpowszechnione w mediach informacje o jej zaślubinach z 19‑letnim Bogdanem Trojanem, które wywołały duże poruszenie. Gabor zakomentowała również komentarze publiczne i wyraziła zadowolenie z nowego etapu życia.');
